public final class DatabaseConnectionPool {
    private static final DatabaseConnectionPool INSTANCE = new DatabaseConnectionPool();
    private final String connectionUrl;

    // Private constructor prevents external instantiation
    private DatabaseConnectionPool() {
        this.connectionUrl = "jdbc:postgresql://localhost:5432/production";
    }

    // Public static method acting as the global access point
    public static DatabaseConnectionPool getInstance() {
        return INSTANCE;
    }

    // Regular method operating on the instance state
    public void executeQuery(String sql) {
        System.out.println("Executing against: " + connectionUrl);
    }
}
